<script setup lang="ts">import {reactive} from 'vue';const emit=defineEmits<{save:[value:Record<string,string>];cancel:[]}>();const form=reactive({title:'',type:'',applicantName:'',customer:'',comment:''});function save(){if(!form.title.trim()||!form.type.trim())return;emit('save',{...form});}</script>
<template><form class="approval-form" @submit.prevent="save"><label>审批标题<input v-model="form.title" placeholder="请输入审批标题" required /></label><label>审批类型<input v-model="form.type" placeholder="例如：合同、付款" required /></label><label>申请人<input v-model="form.applicantName" placeholder="请输入申请人" /></label><label>关联客户<input v-model="form.customer" placeholder="请输入客户名称" /></label><label>申请说明<textarea v-model="form.comment" rows="4" placeholder="请输入申请说明"></textarea></label><div class="form-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button type="submit" class="primary">提交审批</button></div></form></template>
